// End-to-end assertions for the two routes that need no authentication: they can be reached
// without credentials, and **leak no instance data**.
//
// # Why this layer is in httpd and not in the openapi package
//
// Tests in the openapi package can only check "what is in the generated bytes". What is checked here
// is two things about how it is wired:
//
//	1. The two routes really are registered on the **bare mux** (they pass without credentials).
//	   The openapi package cannot see the wiring; it does not know whether httpd mounted them on
//	   authorized. If mounted wrong, production shows "agents cannot get the docs, and the error is
//	   401 please log in".
//	2. The responses contain **no seed data**. This can only be checked by starting the service
//	   with a real core + real seed: with an empty Store, the assertion "no workspace names" would
//	   pass falsely because there are no workspaces at all.
//
// The second is the focus of this file. It guards against **future changes**: today the two
// handlers have no Store, but if someday someone wants to put "which providers this deployment
// enabled" into the spec, this test turns red right away.

package httpd

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/chyroc/ama/server/openapi"
)

// TestPublicRoutesRegistered checks that the two routes can be reached without any credentials.
//
// **This pins where they are wired.** Registering them on authorized (instead of the bare mux)
// would return 401 here, exactly the production symptom "agents cannot read the docs", while the
// error says "please log in", which does not point at all to the real cause "the docs endpoint is
// blocked by authentication".
func TestPublicRoutesRegistered(t *testing.T) {
	srv := newRBACServer(t)

	cases := []struct {
		path        string
		contentType string
	}{
		{openapi.PathSpec, "application/json"},
		{openapi.PathLLMsTxt, "text/markdown"},
	}

	for _, tc := range cases {
		t.Run(tc.path, func(t *testing.T) {
			// **Deliberately no credentials**: no cookie, no Bearer, no api_key.
			req := httptest.NewRequest(http.MethodGet, tc.path, nil)
			rec := httptest.NewRecorder()
			srv.ServeHTTP(rec, req)

			if rec.Code != http.StatusOK {
				t.Fatalf("不带凭据访问 %s 得到 %d，期望 200。"+
					"这两条必须免鉴权——agent 得先读懂平台才可能去认证。",
					tc.path, rec.Code)
			}
			if got := rec.Header().Get("Content-Type"); !strings.Contains(got, tc.contentType) {
				t.Errorf("%s 的 Content-Type 是 %q，期望含 %q", tc.path, got, tc.contentType)
			}
			if rec.Body.Len() == 0 {
				t.Errorf("%s 回了空 body", tc.path)
			}
		})
	}
}

// TestPublicSpecIsValidJSON checks that the spec response is a parsable OpenAPI document.
//
// go:embed of a broken file (e.g. a generator that wrote half of it) is not a compile error; it only
// gives agents something they cannot parse, and that error happens on the agent's side, with
// nothing in our logs.
func TestPublicSpecIsValidJSON(t *testing.T) {
	srv := newRBACServer(t)
	req := httptest.NewRequest(http.MethodGet, openapi.PathSpec, nil)
	rec := httptest.NewRecorder()
	srv.ServeHTTP(rec, req)

	var doc struct {
		OpenAPI string         `json:"openapi"`
		Paths   map[string]any `json:"paths"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &doc); err != nil {
		t.Fatalf("spec 响应不是合法 JSON: %v", err)
	}
	if !strings.HasPrefix(doc.OpenAPI, "3.1") {
		t.Errorf("openapi 版本是 %q，期望 3.1.x", doc.OpenAPI)
	}
	if len(doc.Paths) == 0 {
		t.Error("spec 里一条路径都没有")
	}
}

// TestPublicRoutesExposeNoTenantData is a **security assertion**: responses that need no
// authentication must not contain any instance data.
//
// Start the service with a real core + real seed (newRBACServer), then search both responses for
// workspace names, workspace keys, agent names and member emails that really exist in the seed. A
// match means this unauthenticated endpoint has become an information leak.
//
// # Why a service with seed data is required
//
// With an empty Store, "the response does not contain ws_demo" would **pass falsely** because there
// is no ws_demo at all; the test would be green but check nothing. Seed data gives the assertion a
// real target.
func TestPublicRoutesExposeNoTenantData(t *testing.T) {
	srv := newRBACServer(t)

	// First confirm the targets really are in the database: if the seed changed and these values no
	// longer exist, the assertions below would be idle. **This step keeps the test from rotting by
	// itself.**
	assertSeedDataReachable(t, srv)

	// Things that really exist in the seed. Finding any of them means a leak.
	forbidden := map[string]string{
		"ws_demo":           "空间 id",
		"growth":            "空间 key",
		"alice@example.com": "成员邮箱（owner）",
		"dave@example.com":  "成员邮箱（viewer）",
	}

	for _, path := range []string{openapi.PathSpec, openapi.PathLLMsTxt} {
		req := httptest.NewRequest(http.MethodGet, path, nil)
		rec := httptest.NewRecorder()
		srv.ServeHTTP(rec, req)
		body := rec.Body.String()

		for needle, what := range forbidden {
			if strings.Contains(body, needle) {
				t.Errorf("❌ %s 的响应里出现了%s（%q）——这条接口免鉴权，"+
					"任何实例数据出现在这里都是信息泄露。\n"+
					"它只该描述**结构**（字段名、路径、权限档位），不该含**内容**。",
					path, what, needle)
			}
		}
	}
}

// TestPublicRoutesLeakNoCredentials checks that the responses contain nothing shaped like a credential.
//
// It is separate from the previous one because **the check is different**: that one searches for
// specific seed values, this one for patterns that "look like credentials". The latter catches
// "someone wrote a real key into the docs as an example", which seed values cannot find, and once
// that happens a credential is published on an unauthenticated endpoint.
func TestPublicRoutesLeakNoCredentials(t *testing.T) {
	srv := newRBACServer(t)

	for _, path := range []string{openapi.PathSpec, openapi.PathLLMsTxt} {
		req := httptest.NewRequest(http.MethodGet, path, nil)
		rec := httptest.NewRecorder()
		srv.ServeHTTP(rec, req)
		body := rec.Body.String()

		// A real API Key in plain text looks like amak_ + 43 base64 characters.
		// `amak_` appearing in the docs is normal (to explain the prefix), but **followed by a long
		// run** it is not.
		for i := 0; i+len(auth_keyPrefix) < len(body); i++ {
			if !strings.HasPrefix(body[i:], auth_keyPrefix) {
				continue
			}
			rest := body[i+len(auth_keyPrefix):]
			if runLen := credentialRunLength(rest); runLen >= 24 {
				t.Errorf("❌ %s 里出现了疑似真实 API Key（%s 后面跟着 %d 个连续凭据字符）。"+
					"免鉴权接口上不能有任何真凭据，哪怕是当例子写的。",
					path, auth_keyPrefix, runLen)
			}
		}

		// The fixed API Key used in tests must not appear either (it stands for "credentials in
		// config").
		if strings.Contains(body, testAPIKey) {
			t.Errorf("❌ %s 里出现了固定 API Key", path)
		}
	}
}

// auth_keyPrefix is the same as auth.KeyPrefix.
//
// Not importing auth just for one constant: this file already imports it (newRBACServer needs it);
// it is defined separately here so "what to search for" is visible at a glance in this file.
const auth_keyPrefix = "amak_"

// credentialRunLength counts how many consecutive "credential characters" (base64url alphabet) are
// at the start.
func credentialRunLength(s string) int {
	n := 0
	for n < len(s) {
		c := s[n]
		isBase64 := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '-' || c == '_'
		if !isBase64 {
			break
		}
		n++
	}
	return n
}

// assertSeedDataReachable confirms the seed data is really in the database.
//
// **This is a meta test**: it makes sure the two security assertions above have real targets. If
// the seed changed and ws_demo no longer existed, "the response does not contain ws_demo" would
// pass falsely; the security tests would look green while checking nothing.
func assertSeedDataReachable(t *testing.T, srv http.Handler) {
	t.Helper()
	rec := httptest.NewRecorder()
	srv.ServeHTTP(rec, asRole(http.MethodGet, "/api/workspaces", roleOwner, ""))
	if rec.Code != http.StatusOK {
		t.Fatalf("拿不到种子空间列表（%d），安全断言会失去靶子", rec.Code)
	}
	if !strings.Contains(rec.Body.String(), "ws_demo") {
		t.Fatal("种子里没有 ws_demo 了——请更新 TestPublicRoutesExposeNoTenantData 的 forbidden 列表，" +
			"否则那条安全断言是空转")
	}
}
